// 1. 取得全域靜態儲存區
const staticData = $getWorkflowStaticData('global');
const userIds = Object.keys(staticData);
const beforeCount = userIds.length;
const clearedList = [];

// 2. 執行強制清理
userIds.forEach(id => {
  // 紀錄被刪除的 ID
  clearedList.push(id);
  // 強制刪除，不論其內容是數字、物件還是字串
  delete staticData[id];
});

// 3. 檢查是否真的清空了 (防呆)
const afterCount = Object.keys(staticData).length;

// 4. 格式化回報訊息給 Telegram
const now = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });
let reportMessage = "";

if (beforeCount > 0) {
  reportMessage = `🧹 **自動大掃除報告**\n`;
  reportMessage += `-------------------------\n`;
  reportMessage += `清除數量：${beforeCount} 筆\n`;
  reportMessage += `清理時間：${now}\n\n`;
  reportMessage += `**清除清單：**\n`;
  clearedList.forEach((id, index) => {
    reportMessage += `${index + 1}. \`${id}\`\n`;
  });

  if (afterCount > 0) {
    reportMessage += `\n⚠️ 警告：仍有 ${afterCount} 筆資料未被清除！`;
  } else {
    reportMessage += `\n✨ 暫存區已完全清空。`;
  }
} else {
  reportMessage = `ℹ️ 大掃除執行完畢\n暫存區原本就是空的。\n時間：${now}`;
}

return {
  tgMessage: reportMessage,
  clearedCount: beforeCount,
  remainingCount: afterCount
};

// 1. 取得目前 global 的所有暫存內容
const staticData = $getWorkflowStaticData('global');
const userIds = Object.keys(staticData);
const count = userIds.length;

// 2. 格式化輸出內容
let message = "";
const now = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });

if (count === 0) {
  message = `ℹ️ 目前暫存區是空的\n時間：${now}`;
} else {
  message = `📋 **暫存清單查詢**\n`;
  message += `-------------------------\n`;
  message += `總計：${count} 筆\n`;
  message += `時間：${now}\n\n`;
  message += `項目內容：\n`;

  userIds.forEach((id, index) => {
    const data = staticData[id];
    let displayContent = "";

    // 判斷是否為時間戳數字
    if (typeof data === 'number' && data > 1000000000000) {
      displayContent = new Date(data).toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });
    } else {
      displayContent = typeof data === 'object' ? JSON.stringify(data) : data;
    }

    message += `${index + 1}. \`${id}\`\n最後活動：${displayContent}\n\n`;
  });
}

return {
  tgMessage: message,
  count: count
};

// 1. 取得 Google Sheets 查表後的結果
const sheetData = items[0].json;

// 2. 取得 Webhook 原始資料
const webhookNode = $node["發票明細回傳"].json;
const questions = webhookNode.body.submission.questions;

// 3. 提取表單明細
const period = questions.find(q => q.name === '發票期數')?.value || "";
const isUrgent = questions.find(q => q.name === '是否急用')?.value ? " 🔴急件" : "";

// 整理購買清單 (只列出有填數量的項目)
const details = questions
  .filter(q => q.type === 'MultipleChoice' && q.value !== null && q.name !== '發票期數')
  .map(q => `• ${q.name}：${q.value} 本`)
  .join('\n');

// 4. 組裝 Flex Message (隱藏標題，直接顯示參數版)
const flexContent = {
  "type": "bubble",
  "body": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      { "type": "text", "text": "✅ 收到發票申請", "weight": "bold", "color": "#1DB446", "size": "md" },
      { "type": "text", "text": sheetData["客戶名稱"], "weight": "bold", "size": "xl", "margin": "md", "wrap": true },
      { "type": "text", "text": `統一編號：${sheetData["統一編號"] || "無"}`, "size": "sm", "color": "#aaaaaa" },
      { "type": "separator", "margin": "lg" },
      {
        "type": "box",
        "layout": "vertical",
        "margin": "lg",
        "spacing": "sm",
        "contents": [
          // 直接顯示期數與急件，不帶標題
          { 
            "type": "text", 
            "text": `${period}${isUrgent}`, 
            "weight": "bold", 
            "size": "xl", 
            "color": "#111111",
            "margin": "md"
          },
          { "type": "text", "text": "申請明細：", "color": "#aaaaaa", "size": "xl", "margin": "lg" },
          { 
            "type": "text", 
            "text": details || "未選擇明細", 
            "wrap": true, 
            "color": "#111111", 
            "size": "lg", 
            "weight": "bold" 
          }
        ]
      }
    ]
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      { "type": "text", "text": "我們會儘速為您辦理，謝謝！", "size": "md", "color": "#aaaaaa", "align": "center" }
    ]
  }
};

return {
  userId: webhookNode.body.submission.urlParameters.find(p => p.name === 'uid')?.value,
  clientName: sheetData["客戶名稱"],
  flexJson: JSON.stringify(flexContent),
  // 將 \n 替換為 <br>
  emailBody: `客戶：${sheetData["客戶名稱"]}<br>期數狀態：${period}${isUrgent}<br>明細：<br>${details}`
};

// 取得 Webhook 傳來的原始資料
const body = items[0].json.body;

// 1. 提取網址參數中的 client (例如: A21-23829234)
const urlParams = body.submission.urlParameters;
const clientCode = urlParams.find(p => p.name === 'client')?.value;

// 2. 提取網址參數中的 uid (LINE UserID)
const uid = urlParams.find(p => p.name === 'uid')?.value;

// 3. 提取表單中的其他欄位 (可選，供後續發信使用)
const questions = body.submission.questions;
const isUrgent = questions.find(q => q.name === '是否急用')?.value || false;

// 回傳整理後的乾淨資料
return {
  searchKey: clientCode, // 這將作為 Google Sheets 查詢的關鍵字
  lineUserId: uid,
  isUrgent: isUrgent,
  originalBody: body // 保留原始資料備用
};

// 取得台灣當前時間字串
const now = new Date();
const timeString = now.toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });

// 組裝 Telegram HTML 格式訊息
const tgMessage = `<b>🔥 試算表預熱完成通知</b>\n\n` +
                  `• <b>預熱項目</b>：LINE ID、帳單總表\n` +
                  `• <b>執行時間</b>：<code>${timeString}</code>\n` +
                  `• <b>連線狀態</b>：Google API 已保持熱啟動 🟢`;

return [{
  json: {
    tgMessage: tgMessage
  }
}];

